import { HttpError } from "wasp/server";
import type { OnBeforeSignupHook } from "wasp/server/auth";

/**
 * Enforces that any user signing up with the "ADMIN" role must use a
 * username that ends with "_admin" (e.g. "super_admin").
 */
export const onBeforeSignup: OnBeforeSignupHook = async ({
  providerId,
  req,
}) => {
  const body = (req.body ?? {}) as { role?: unknown };
  const requestedRole = body.role;

  if (requestedRole === "ADMIN") {
    const username = providerId.providerUserId;
    if (!username.endsWith("_admin")) {
      throw new HttpError(
        403,
        "Usernames for the ADMIN role must end with '_admin' (e.g. 'super_admin').",
      );
    }
  }
};

import { defineUserSignupFields } from "wasp/server/auth";

const VALID_ROLES = ["ANALYST", "MANAGER", "ADMIN"] as const;
type Role = (typeof VALID_ROLES)[number];

function isValidRole(value: unknown): value is Role {
  return typeof value === "string" && (VALID_ROLES as readonly string[]).includes(value);
}

export const userSignupFields = defineUserSignupFields({
  role: (data: Record<string, unknown>) => {
    const role = data.role;
    return isValidRole(role) ? role : "ANALYST";
  },
});

import { HttpError } from "wasp/server";
import type { GetDocuments, GetAuditLogs } from "wasp/server/operations";
import type { Document, AuditLog } from "wasp/entities";

export const getDocuments: GetDocuments<void, Document[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.Document.findMany({
    orderBy: { id: "asc" },
  });
};

export const getAuditLogs: GetAuditLogs<void, AuditLog[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only ADMIN users can view audit logs.");
  }

  return context.entities.AuditLog.findMany({
    orderBy: { id: "asc" },
  });
};

import { HttpError } from "wasp/server";
import type {
  CreateDocument,
  UpdateDocument,
  DeleteDocument,
} from "wasp/server/operations";
import type { Document } from "wasp/entities";

type CreateDocumentInput = {
  title: string;
  content: string;
};

type UpdateDocumentInput = {
  id: number;
  title: string;
  content: string;
};

type DeleteDocumentInput = {
  id: number;
};

export const createDocument: CreateDocument<
  CreateDocumentInput,
  Document
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(
      403,
      "Only MANAGER and ADMIN users can create documents.",
    );
  }

  const document = await context.entities.Document.create({
    data: {
      title: args.title,
      content: args.content,
      owner: { connect: { id: context.user.id } },
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "CREATE",
      entityName: "Document",
      entityId: document.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });

  return document;
};

export const updateDocument: UpdateDocument<
  UpdateDocumentInput,
  Document
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  if (context.user.role !== "MANAGER" && context.user.role !== "ADMIN") {
    throw new HttpError(
      403,
      "Only MANAGER and ADMIN users can update documents.",
    );
  }

  const document = await context.entities.Document.update({
    where: { id: args.id },
    data: {
      title: args.title,
      content: args.content,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "UPDATE",
      entityName: "Document",
      entityId: document.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });

  return document;
};

export const deleteDocument: DeleteDocument<
  DeleteDocumentInput,
  void
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Only ADMIN users can delete documents.");
  }

  await context.entities.Document.delete({
    where: { id: args.id },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "DELETE",
      entityName: "Document",
      entityId: args.id,
      userId: context.user.id,
      payload: JSON.stringify({ id: args.id }),
    },
  });
};

import { login, signup } from "wasp/client/auth";
import { useState } from "react";
import { useNavigate, Link } from "react-router";

import "./auth.css";

export function SignupPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("ANALYST");
  const [error, setError] = useState<Error | null>(null);
  const navigate = useNavigate();

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    try {
      await signup({ username, password, role });
      await login({ username, password });
      navigate("/");
    } catch (err) {
      setError(err as Error);
    }
  }

  return (
    <div className="auth-page">
      <h2>Sign Up</h2>
      {error && <p className="error">Error: {error.message}</p>}
      <form onSubmit={handleSubmit}>
        <label htmlFor="username">Username</label>
        <input
          id="username"
          name="username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Username"
        />

        <label htmlFor="password">Password</label>
        <input
          id="password"
          name="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Password"
        />

        <label htmlFor="role">Role</label>
        <select
          id="role"
          name="role"
          value={role}
          onChange={(e) => setRole(e.target.value)}
        >
          <option value="ANALYST">ANALYST</option>
          <option value="MANAGER">MANAGER</option>
          <option value="ADMIN">ADMIN</option>
        </select>

        <button id="signup-btn" type="submit">
          Sign Up
        </button>
      </form>
      <p>
        Already have an account? <Link to="/login">Log in</Link>
      </p>
    </div>
  );
}

export function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<Error | null>(null);
  const navigate = useNavigate();

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    try {
      await login({ username, password });
      navigate("/");
    } catch (err) {
      setError(err as Error);
    }
  }

  return (
    <div className="auth-page">
      <h2>Log In</h2>
      {error && <p className="error">Error: {error.message}</p>}
      <form onSubmit={handleSubmit}>
        <label htmlFor="username">Username</label>
        <input
          id="username"
          name="username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Username"
        />

        <label htmlFor="password">Password</label>
        <input
          id="password"
          name="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Password"
        />

        <button id="login-btn" type="submit">
          Log In
        </button>
      </form>
      <p>
        Don't have an account? <Link to="/signup">Sign up</Link>
      </p>
    </div>
  );
}

